def transform(grid):
    h, w = len(grid), len(grid[0])
    A = B = None; orient = None
    for i in range(h):
        if len(set(grid[i])) == 1:
            a = [r[:w] for r in grid[:i]]; b = [r[:w] for r in grid[i+1:]]
            if a and b and len(a) == len(b):
                A, B, orient = a, b, 'row'; break
    if A is None:
        for j in range(w):
            if len(set(grid[i][j] for i in range(h))) == 1:
                a = [r[:j] for r in grid]; b = [r[j+1:] for r in grid]
                if a and b and len(a[0]) == len(b[0]):
                    A, B, orient = a, b, 'col'; break
    cnt = collections.Counter()
    for r in range(len(A)):
        for c in range(len(A[0])):
            if A[r][c] == B[r][c]:
                cnt[A[r][c]] += 1
    bg = cnt.most_common(1)[0][0]
    return [[3 if A[r][c] == B[r][c] else bg for c in range(len(A[0]))] for r in range(len(A))]

def transform(grid):
    from collections import Counter
    g=[r[:] for r in grid]; h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    rows=[i for i in range(h) if any(x!=bg for x in g[i])]
    if not rows: return g
    bs=[];cur=[rows[0]]
    for i in rows[1:]:
        if i==cur[-1]+1: cur.append(i)
        else: bs.append(cur);cur=[i]
    bs.append(cur)
    def patt(r): return {c for c in range(w) if g[r][c]!=bg}
    def best_shift(pa,pb):
        return max(sum(1 for c in pa if 0<=c+s<w and (c+s) in pb) for s in range(-w,w))
    touch=[b for b in bs if any(g[r][w-1]!=bg for r in b)]
    refs=touch or [bs[0]]
    targets=[b for b in bs if b not in refs]
    shifts=[]
    for tb in targets:
        for k in range(min(len(refs[0]),len(tb))):
            pa,pb=patt(refs[0][k]),patt(tb[k])
            if pa and pb:
                b_=best_shift(pa,pb)
                shifts+=[s for s in range(0,w) if sum(1 for c in pa if c+s<w and (c+s) in pb)==b_]
    if not shifts: return g
    s=Counter(shifts).most_common(1)[0][0]
    for tb in targets:
        for k in range(min(len(refs[0]),len(tb))):
            ra,rb=refs[0][k],tb[k]
            pa,pb=patt(ra),patt(rb)
            if not pa or not pb: continue
            rbm=max(pb)
            for c in pa:
                cc=c+s
                if cc<w and g[rb][cc]==bg and cc>rbm: g[rb][cc]=1
    return g

